def suggestions_table():
    items=[
      ('SUG-01','P1','Keep B separate; evaluate selling A for diversified equities','Evaluate net sale proceeds, tax reserves, diversification and drawdown tolerance before choosing.','No guaranteed winner or tax-free sale; equity loss risk remains.','basis stocks'),
      ('SUG-02','P1','Keep B separate; compare a balanced portfolio if A is sold','Compare equity/bill allocations with taxes, fees, rebalancing and needed withdrawals. No fixed allocation is selected.','Lower equity exposure changes both risk and upside; staged entry cannot eliminate losses.','stocks bills'),
      ('SUG-03','P1','Keep B separate; compare bills / cash if A is sold','Consider short-term liquidity and preservation with federal interest tax and changing auction yields.','Inflation/reinvestment risk; distinguish insured deposits from Treasury securities.','bills fdic'),
      ('SUG-04','P1','Keep B separate; evaluate renting A','Obtain rent, reassessed tax, insurance, management and repair evidence; compare after-tax liquidation.','Keeps concentrated property exposure and landlord duties. No verified household net yield.','prop19 rental insurance'),
      ('SUG-05','P1','Live in A; evaluate any lawful B rental use','Confirm genuine residence, eligible exclusion, legal unit status and achievable rent first.','Lifestyle benefit may justify costs; no automatic extra rent, exemption or unit-count deduction.','prop19 rental rentlocal homeex'),
      ('SUG-06','P1','Live in A; evaluate personal use of any B space','Evaluate actual use and opportunity cost instead of calling all vacant space financially worthless.','No extra rent assumed; personal flexibility and carrying costs must be priced separately.','rental prop19'),
      ('S01','P0','Separate private evidence workspace','Keep the public dashboard generic; establish authenticated, encrypted document storage outside this public repo.','Stops publication of source bills/trust records. Requires privacy and access-control review.','githubvisibility'),
      ('S02','P1','Evidence-first model inputs','After secure collection, have advisers verify each value, date and unit before using it in a private model.','Prevents a contextual source link from being mistaken for factual confirmation.','basis insurance'),
      ('S03','P1','Property-specific insurance comparison','Obtain comparable quotes for each proposed occupancy type (owner-occupied, rental or mixed-use).','May change carry costs enough to change the decision; public premium remains blank.','insurance'),
      ('S04','P1','Cash and tax reserve policy','Before any investment, verify estate payment timing, repairs and household withdrawals.','Reduces forced-sale risk; reserve amount depends on missing obligations.','706 bills fdic'),
      ('S05','P1','Independent model audit','Use identical dates, after-tax liquidation and common B treatment; compare sensitivities and actual tax returns.','Avoids rankings driven by inconsistent tax or double counting.','gains rental'),
      ('S06','P2','Shared approval audit trail','Add an authenticated review workflow only after scope, storage and reviewer access are approved.','Current browser-only preferences are not team approvals.','estate'),
      ('S07','P2','Dated law-change monitoring','Review IRS, BOE, California rent law, Congress and local rent notices annually and before transfer/occupancy changes.','Avoids treating old law or an introduced bill as current. Not an automated service today.','new prop19 ab1482 rentlocal hr5336 s4122'),
      ('S09','P2','Side-by-side financial-path selector','Add a private comparison only after evidence, security, access and reviewer approval are in place.','Compare the actual transfer year and paths without publishing household inputs.','prop19 basis githubvisibility'),
      ('S10','P2','Show sensitivities and evidence readiness','Add approved ranges for returns, rents, repairs and taxes plus an authenticated document-readiness tracker.','Ranges must be assumptions, not verified confidence intervals; dates and owners require private access.','rental stocks insurance'),
      ('S11','P2','One-page adviser meeting export','Create a reviewed single-page brief with conditional paths, deadlines and remaining evidence; current Print brief prints the selected page.','No automatic PDF with private data; separate financial paths from site changes.','706 notice prop19'),
      ('S08','P2','Evidence-backed stress analysis','Use documented official historical series and separately verified portfolio data for a non-wrapped replay and withdrawal sensitivity. FHFA HPI can inform housing context but is not a single-home forecast.','No historical replay, portfolio backtest or probability is currently published. Historical data does not guarantee future results.','fhfa stocks cpi')]
    # Source-linked rows retain semantic headers; selects affect review state only.
    out='<section class="table-section"><h2>Financial paths awaiting evidence and review</h2><p class="table-note">Options for review only; no path is endorsed or ranked. Official links support context, not a household result.</p><div class="table-scroll" tabindex="0" aria-label="Suggestion review queue"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in ['ID / priority','Suggestion','Scope','Benefit / trade-off','Review preference','Status','Official context'])+'</tr></thead><tbody>'
    for idx,(ident,priority,title,scope,benefit,source) in enumerate(items):
        if idx == 6:
            out+='</tbody></table></div></section><section class="table-section"><h2>Site improvements awaiting approval</h2><p class="table-note">Changes to the product, separate from financial decisions. Preference is local only.</p><div class="table-scroll" tabindex="0" aria-label="Site improvement review queue"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in ['ID / priority','Suggestion','Scope','Benefit / trade-off','Review preference','Status','Official context'])+'</tr></thead><tbody>'
        out+=f'<tr><td>{ident} · {priority}</td><td>{E(title)}</td><td>{E(scope)}</td><td>{E(benefit)}</td><td><select class="review-choice" data-id="{ident}" aria-label="Review preference for {ident}">'+''.join(f'<option value="{v}">{v}</option>' for v in ['Not reviewed','Investigate','Preferred path','Defer'])+'</select></td><td><span class="badge guidance">Guidance</span></td><td>'+refs(source)+'</td></tr>'
    return out+'</tbody></table></div></section>'
